// Calcula fechas: últimos 7 días vs los 7 anteriores (para detectar tendencias).
const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const prevEnd = new Date(start.getTime() - 1 * 24 * 60 * 60 * 1000);
const prevStart = new Date(prevEnd.getTime() - 7 * 24 * 60 * 60 * 1000);
const fmt = d => d.toISOString().slice(0, 10);
return [{
  json: {
    currentRange: { start: fmt(start), end: fmt(end) },
    previousRange: { start: fmt(prevStart), end: fmt(prevEnd) },
    siteUrl: $env.TOROMAC_GSC_SITE_URL
  }
}];

// Detecta issues a partir de los datos GSC:
// - LOW_CTR: queries con impresiones >50 y CTR <1%
// - GENERIC: cualquier query con posición media >20 e impresiones >100 (oportunidad)
const data = $input.first().json;
const rows = data.rows || [];
const issues = [];
for (const r of rows) {
  const [query, page] = r.keys;
  const { clicks = 0, impressions = 0, ctr = 0, position = 0 } = r;
  // CTR bajo con tráfico
  if (impressions > 50 && ctr < 0.01) {
    issues.push({
      tipo: 'LOW_CTR',
      severidad: impressions > 200 ? 'alta' : 'media',
      url: page,
      detalle: `Query "${query}" — ${impressions} impresiones, CTR ${(ctr*100).toFixed(2)}%`,
      metrica: `CTR ${(ctr*100).toFixed(2)}% en ${impressions} imp`,
      accion_propuesta: 'Revisar title/meta para mejorar CTR'
    });
  }
  // Oportunidad: posición lejana con impresiones (no es realmente un "issue" pero lo registramos)
  if (impressions > 100 && position > 20) {
    issues.push({
      tipo: 'OPPORTUNITY',
      severidad: 'baja',
      url: page,
      detalle: `Query "${query}" — posición ${position.toFixed(1)} con ${impressions} imp`,
      metrica: `pos ${position.toFixed(1)} · ${impressions} imp`,
      accion_propuesta: 'Candidata a artículo nuevo del Writer'
    });
  }
}
const critical = issues.filter(i => i.severidad === 'alta');
const siteUrl = $('Build Date Ranges').item.json.siteUrl;
return [{
  json: {
    total_rows: rows.length,
    total_issues: issues.length,
    critical_count: critical.length,
    issues,
    critical,
    // Campos para Append Changelog (autoMap)
    timestamp: new Date().toISOString(),
    agente: 'gsc',
    accion: 'weekly_scan',
    target: siteUrl,
    resultado: 'success (' + issues.length + ' issues)'
  }
}];

// Itera issues en items separados para append en Sheet.
// Remapea las keys para que matcheen las columnas de la hoja gsc-issues.
return $input.first().json.issues.map(i => ({
  json: {
    fecha: new Date().toISOString(),
    tipo: i.tipo,
    severidad: i.severidad,
    url_afectada: i.url,
    detalle: i.detalle,
    metrica: i.metrica,
    accion_propuesta: i.accion_propuesta,
    estado: 'nuevo'
  }
}));

